CREATE TABLE api_keys(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,client_id BINARY(16) NOT NULL,environment_id BINARY(16) NOT NULL,key_hash VARCHAR(64) NOT NULL UNIQUE,key_prefix VARCHAR(16) NOT NULL,last_four VARCHAR(4) NOT NULL,scopes_json TEXT NOT NULL,ip_allowlist_json TEXT NOT NULL,quota BIGINT NOT NULL,status VARCHAR(30) NOT NULL,expires_at TIMESTAMP(6),revoked_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL,rotated_at TIMESTAMP(6),version BIGINT NOT NULL,INDEX idx_api_key_client(client_id));